INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist jede Änderung im Projekt sofort umzusetzen?', 2, '[{"text": "Nein", "correct": true, "because": "Bewertung ist nötig"}, {"text": "Ja", "correct": false, "because": "Ungeprüft riskant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welchen Schritt mache ich zuerst, wenn eine Anpassung vorgeschlagen wird?', 3, '[{"text": "Auswirkungen prüfen", "correct": true, "because": "Risiken einschätzen"}, {"text": "Sofort umsetzen", "correct": false, "because": "Fehlt Analyse"}, {"text": "Team ignorieren", "correct": false, "because": "Zusammenarbeit nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren berücksichtige ich bei einer Änderung?', 5, '[{"text": "Kosten", "correct": true, "because": "Budget beeinflusst"}, {"text": "Zeitplan", "correct": true, "because": "Verzögerungen möglich"}, {"text": "Persönliche Vorlieben", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Änderungen brauchen Dokumentation. b) Sie verzögern immer.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Verzögerung nicht zwangsläufig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Bewertung eines Vorschlags?', 4, '[{"text": "Teammeinung", "correct": false, "because": "Wichtig für Akzeptanz"}, {"text": "Machbarkeit", "correct": false, "because": "Entscheidend für Umsetzung"}, {"text": "Gerüchte", "correct": true, "because": "Keine Faktenbasis"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob jede Änderung genehmigt werden muss?', 2, '[{"text": "Ja", "correct": true, "because": "Kontrolle sichern"}, {"text": "Nein", "correct": false, "because": "Prozess erfordert es"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt die Kommunikation bei Anpassungen?', 3, '[{"text": "Alle informieren", "correct": true, "because": "Transparenz schaffen"}, {"text": "Nur Chefs briefen", "correct": false, "because": "Team ausgeschlossen"}, {"text": "Schweigen", "correct": false, "because": "Verwirrung riskieren"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahmen sichern den Änderungsprozess?', 5, '[{"text": "Priorisierung", "correct": true, "because": "Wichtiges zuerst"}, {"text": "Rückverfolgbarkeit", "correct": true, "because": "Nachvollziehbarkeit"}, {"text": "Spontane Umsetzung", "correct": false, "because": "Chaos möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Änderungen sind riskant. b) Sie brauchen keinen Plan. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Planung essenziell"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, um Anpassungen zu steuern?', 4, '[{"text": "Klarer Prozess", "correct": false, "because": "Struktur nötig"}, {"text": "Genehmigung", "correct": false, "because": "Kontrolle wichtig"}, {"text": "Unnötige Meetings", "correct": true, "because": "Zeitverschwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind Änderungen immer teuer?', 2, '[{"text": "Nein", "correct": true, "because": "Kann auch sparen"}, {"text": "Ja", "correct": false, "because": "Kontextabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schritte helfen bei der Umsetzung?', 4, '[{"text": "Risikoanalyse", "correct": true, "because": "Probleme vorhersehen"}, {"text": "Testphase", "correct": true, "because": "Fehler vermeiden"}, {"text": "Sofortiger Rollout", "correct": false, "because": "Riskant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Änderungen nur Chaos bringen. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Gesteuert nützlich"}, {"text": "Ja", "correct": false, "because": "Mit Planung effektiv"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei einem Änderungsvorschlag?', 3, '[{"text": "Auswirkung abschätzen", "correct": true, "because": "Entscheidungsgrundlage"}, {"text": "Schnell zustimmen", "correct": false, "because": "Unüberlegt riskant"}, {"text": "Ablehnen", "correct": false, "because": "Chancen verpassen"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Änderungen brauchen Tests. b) Sie sind immer spontan.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Spontaneität untypisch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bringt ein guter Änderungsprozess?', 5, '[{"text": "Kontrolle behalten", "correct": true, "because": "Risiken minimieren"}, {"text": "Flexibilität erhöhen", "correct": true, "because": "Anpassung möglich"}, {"text": "Mehr Bürokratie", "correct": false, "because": "Nicht Ziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Umsetzung unwichtig?', 3, '[{"text": "Planung", "correct": false, "because": "Struktur essenziell"}, {"text": "Rückmeldung", "correct": false, "because": "Verbesserung fördern"}, {"text": "Zufällige Änderungen", "correct": true, "because": "Chaos erzeugen"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann ich Änderungen ohne Analyse machen?', 3, '[{"text": "Nein", "correct": true, "because": "Risiken unklar"}, {"text": "Ja", "correct": false, "because": "Analyse notwendig"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Protokoll Pflicht ist?', 2, '[{"text": "Ja", "correct": true, "because": "Nachvollziehbarkeit sichern"}, {"text": "Nein", "correct": false, "because": "Dokumentation nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode wähle ich, um Auswirkungen zu prüfen?', 4, '[{"text": "Risikoabschätzung", "correct": true, "because": "Probleme erkennen"}, {"text": "Sofort umsetzen", "correct": false, "because": "Riskant"}, {"text": "Nichts tun", "correct": false, "because": "Ignoriert Problem"}]');